type RecordItem = { id:string; title:string; type:string; year:number; language:string; collection:string; summary:string; excerpt:string; themes:string[]; source:string; pages?:number; duration?:string; color:string } & SourceRecord;
type HistoryKind = "life"|"book"|"article"|"newspaper"|"movement"|"constitution";
